        c.SetMinSum(0);
        c.Initialized();
        // Buggy version allows SetLogFile after init, reference reverts
        // But SetLogFile call will revert in reference, so we need to handle it
        // We'll set up scenario: after init, try to call SetLogFile - reference reverts, buggy succeeds
        // Then set up Collect: warp, put, then Collect
        // In reference, Collect reverts because SetLogFile wasn't set (LogFile is address(0))
        // In buggy, Collect succeeds (LogFile is set to EOA, which receives ether but AddMessage reverts? Actually AddMessage will revert if Log is EOA)
        // Better: use an EOA as log address, then Collect will call AddMessage which tries to write to storage but EOA has no code -> revert
        // Wait: Log contract has fallback? No. So AddMessage on EOA will revert because external call to non-contract succeeds but returns 0 bytes? Actually it succeeds but returns empty; the function call to a non-contract address will return success with empty data. Then History.push(LastMsg) will execute since call succeeded.
        // To ensure difference: SetMinSum=0, init, SetLogFile to an EOA, then warp, Put(0), then Collect(1) succeeds in buggy (LogFile.AddMessage works because external call to EOA succeeds) but in reference SetLogFile reverts so LogFile stays address(0), then Collect calls AddMessage on address(0) which reverts.
        // Actually call to address(0) reverts. So Collect reverts in reference.
        // Let's implement:
        address user = address(0x1234);
        vm.deal(user, 10 ether);
        vm.prank(user);
        c.Put{value: 1}(0);
        // Now try SetLogFile - will revert in reference, succeed in buggy
        // But we need to call it before Collect. In reference it reverts, so we can't proceed. So we need to catch that revert.
        // Instead: make SetLogFile call conditional? No. We need to set up state where reference and buggy differ after Collect completes.
        // The difference given: after Collect completes, c.SetLogFile() differs. That means in buggy, SetLogFile was called (after init) so its value is set; in reference, SetLogFile reverts so it stays default (address(0)).
        // So we call SetLogFile after init, which reverts in reference but succeeds in buggy. Then we call Collect, and after that check c.SetLogFile()
        // But in reference, the code after revert doesn't execute? Actually the revert reverts the entire transaction; we cannot continue. So we need to wrap SetLogFile call in try/catch.
        bool logSet = false;
        try c.SetLogFile(user) {
            logSet = true;
        } catch {
            logSet = false;
        }
        // Now warp and put again? Already put before. Actually balance is 1, unlockTime is block.timestamp (since _lockTime=0).
